import './App.css';
import EditorPage from './components/EditorPage';
import Home from './components/Home';
import { Route,Routes } from 'react-router-dom';

function App() {
  return (


      <Routes>
     <Route path='/' element={ <Home /> } />
     <Route path='/editor/:roomId' element={ <EditorPage /> } />
    </Routes>
  );
}

export default App;
